+        border: 0;
+        border-radius: 999px;
+        background: linear-gradient(135deg, var(--accent-strong), #6366f1);
+        color: #08111f;
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.06);
+      }
+
+      a:focus-visible,
+      input:focus-visible,
+      button:focus-visible {
+        outline: 3px solid #f8fafc;
+        outline-offset: 3px;
+      }
+
+      @media (max-width: 480px) {
