+                <label for="consent">
+                  I agree to the <a href="#terms-of-use">terms of use</a>
+                  <span class="required-mark" aria-hidden="true">*</span>
+                </label>
+                <p id="consent-help" class="helper-text">
+                  Required to continue.
+                </p>
+              </div>
+            </div>
+          </div>
+        `);
+      }
+
+      function SubmitButton() {
+        return createTemplate('<button type="submit">Agree and continue</button>');
+      }
+
+      function ConsentForm() {
+        const form = createTemplate(`
+          <form novalidate>
+            <div id="form-message" class="status-text" aria-live="polite"></div>
+          </form>
+        `);
+
+        const checkboxField = ConsentField();
+        const submitButton = SubmitButton();
+
+        form.insertBefore(checkboxField, form.firstElementChild);
+        form.append(submitButton);
+
+        const checkbox = checkboxField.querySelector("#consent");
+        const message = form.querySelector("#form-message");
