+          if (existingError) {
+            existingError.remove();
+          }
+          message.textContent = "";
+          message.className = "status-text";
+        };
+
+        const showError = () => {
+          clearError();
+          checkbox.setAttribute("aria-invalid", "true");
+          checkbox.setAttribute("aria-describedby", helperId + " " + errorId);
+          checkboxField.insertAdjacentHTML(
+            "beforeend",
