+
+        checkbox.addEventListener("change", () => {
+          if (checkbox.checked) {
+            clearError();
+          }
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+
+          if (!checkbox.checked) {
+            showError();
+            return;
+          }
+
+          clearError();
+          message.textContent = "Consent recorded. You can continue.";
+        });
+
+        return form;
+      }
+
