    <title>Terms of Use Consent</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.92);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5eefc;
        --muted: #a8b3c7;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --danger: #fca5a5;
        --danger-bg: rgba(127, 29, 29, 0.28);
        --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(56, 189, 248, 0.15), transparent 30%),
          linear-gradient(180deg, #111827 0%, var(--bg) 100%);
        color: var(--text);
      }

      a {
        color: var(--accent);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: -3rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: #ffffff;
        color: #111827;
        font-weight: 700;
      }

      .skip-link:focus {
        top: 1rem;
      }

      main {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 1.5rem;
      }

      .card {
        width: min(100%, 30rem);
        padding: 2rem;
        border: 1px solid var(--panel-border);
        border-radius: 1.5rem;
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(12px);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.75rem, 4vw, 2.2rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--muted);
        line-height: 1.5;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid rgba(125, 211, 252, 0.18);
        border-radius: 1rem;
        background: rgba(15, 23, 42, 0.72);
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.85rem;
      }

      input[type="checkbox"] {
        width: 1.15rem;
        height: 1.15rem;
        margin-top: 0.2rem;
        accent-color: var(--accent-strong);
      }

      label {
        font-size: 1rem;
        line-height: 1.5;
      }

      .required-mark {
        color: #fde68a;
      }

      .helper-text,
      .error-text,
      .status-text {
        margin: 0.75rem 0 0;
        font-size: 0.95rem;
        line-height: 1.45;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
      }

      .error-panel {
        padding: 0.85rem 1rem;
        border: 1px solid rgba(252, 165, 165, 0.45);
        border-radius: 0.9rem;
        background: var(--danger-bg);
      }

      button {
        justify-self: start;
        min-width: 10rem;
        padding: 0.9rem 1.2rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent-strong), #6366f1);
        color: #08111f;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.06);
      }

      a:focus-visible,
      input:focus-visible,
      button:focus-visible {
        outline: 3px solid #f8fafc;
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
        }

        .checkbox-row {
          gap: 0.75rem;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .error-panel,
        button {
          border: 1px solid CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const appRoot = document.getElementById("app");

      const createTemplate = (html) => {
        const template = document.createElement("template");
        template.innerHTML = html.trim();
        return template.content.firstElementChild;
      };

      function ConsentField() {
        return createTemplate(`
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="consent"
                name="consent"
                type="checkbox"
                required
                aria-describedby="consent-help"
              />
              <div>
                <label for="consent">
                  I agree to the <a href="#terms-of-use">terms of use</a>
                  <span class="required-mark" aria-hidden="true">*</span>
                </label>
                <p id="consent-help" class="helper-text">
                  Required to continue.
                </p>
              </div>
            </div>
          </div>
        `);
      }

      function SubmitButton() {
        return createTemplate('<button type="submit">Agree and continue</button>');
      }

      function ConsentForm() {
        const form = createTemplate(`
          <form novalidate>
            <div id="form-message" class="status-text" aria-live="polite"></div>
          </form>
        `);

        const checkboxField = ConsentField();
        const submitButton = SubmitButton();

        form.insertBefore(checkboxField, form.firstElementChild);
        form.append(submitButton);

        const checkbox = checkboxField.querySelector("#consent");
        const message = form.querySelector("#form-message");
        const helperId = "consent-help";
        const errorId = "consent-error";

        const clearError = () => {
          checkbox.removeAttribute("aria-invalid");
          checkbox.setAttribute("aria-describedby", helperId);
          const existingError = checkboxField.querySelector("#" + errorId);
          if (existingError) {
            existingError.remove();
          }
          message.textContent = "";
          message.className = "status-text";
        };

        const showError = () => {
          clearError();
          checkbox.setAttribute("aria-invalid", "true");
          checkbox.setAttribute("aria-describedby", helperId + " " + errorId);
          checkboxField.insertAdjacentHTML(
            "beforeend",
            '<p id="consent-error" class="error-text error-panel">Error: You must agree to the terms of use to continue.</p>'
          );
          message.textContent = "Please review the required consent field.";
          message.className = "status-text error-text";
          checkbox.focus();
        };

        checkbox.addEventListener("change", () => {
          if (checkbox.checked) {
            clearError();
          }
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          if (!checkbox.checked) {
            showError();
            return;
          }

          clearError();
          message.textContent = "Consent recorded. You can continue.";
        });

        return form;
      }

      function App() {
        const main = createTemplate(`
          <main id="main-content">
            <section class="card" aria-labelledby="page-title">
              <h1 id="page-title">Confirm your agreement</h1>
              <p class="intro">
                Review the terms and confirm your consent before proceeding.
              </p>
              <div id="form-slot"></div>
              <p id="terms-of-use" class="helper-text">
                Terms of use cover acceptable use, account responsibilities, and privacy expectations.
              </p>
            </section>
          </main>
        `);

        main.querySelector("#form-slot").append(ConsentForm());
        return main;
      }

      appRoot.append(App());
    </script>
  </body>
</html>
