     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>

     <script>
       const appRoot = document.getElementById("app");

       const createTemplate = (html) => {
         const template = document.createElement("template");
         template.innerHTML = html.trim();
         return template.content.firstElementChild;
       };

       function ConsentField() {
         return createTemplate(`
           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="consent"
                 name="consent"
                 type="checkbox"
                 required
                 aria-describedby="consent-help"
               />
               <div>
                 <label for="consent">
                   I agree to the <a href="#terms-of-use">terms of use</a>
                   <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <p id="consent-help" class="helper-text">
                   Required to continue.
                 </p>
               </div>
             </div>
           </div>
         `);
       }

       function SubmitButton() {
         return createTemplate('<button type="submit">Agree and continue</button>');
       }

       function ConsentForm() {
         const form = createTemplate(`
           <form novalidate>
             <div id="form-message" class="status-text" aria-live="polite"></div>
           </form>
         `);

         const checkboxField = ConsentField();
         const submitButton = SubmitButton();

         form.insertBefore(checkboxField, form.firstElementChild);
         form.append(submitButton);

         const checkbox = checkboxField.querySelector("#consent");
         const message = form.querySelector("#form-message");
         const helperId = "consent-help";
         const errorId = "consent-error";

         const clearError = () => {
           checkbox.removeAttribute("aria-invalid");
           checkbox.setAttribute("aria-describedby", helperId);
           const existingError = checkboxField.querySelector("#" + errorId);
           if (existingError) {
             existingError.remove();
           }
           message.textContent = "";
           message.className = "status-text";
         };

         const showError = () => {
           clearError();
           checkbox.setAttribute("aria-invalid", "true");
           checkbox.setAttribute("aria-describedby", helperId + " " + errorId);
           checkboxField.insertAdjacentHTML(
             "beforeend",
             '<p id="consent-error" class="error-text error-panel">Error: You must agree to the terms of use to continue.</p>'
           );
           message.textContent = "Please review the required consent field.";
           message.className = "status-text error-text";
           checkbox.focus();
         };

         checkbox.addEventListener("change", () => {
           if (checkbox.checked) {
             clearError();
           }
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           if (!checkbox.checked) {
             showError();
             return;
           }

           clearError();
           message.textContent = "Consent recorded. You can continue.";
         });

         return form;
       }

       function App() {
         const main = createTemplate(`
           <main id="main-content">
             <section class="card" aria-labelledby="page-title">
               <h1 id="page-title">Confirm your agreement</h1>
               <p class="intro">
                 Review the terms and confirm your consent before proceeding.
               </p>
               <div id="form-slot"></div>
               <p id="terms-of-use" class="helper-text">
                 Terms of use cover acceptable use, account responsibilities, and privacy expectations.
               </p>
             </section>
           </main>
         `);

         main.querySelector("#form-slot").append(ConsentForm());
         return main;
       }

       appRoot.append(App());
     </script>
   </body>
