const fs = require('fs');
const { chromium } = require('playwright');
(async () => {
  let browser;
  try {
    browser = await chromium.launch();
  } catch (error) {
    if (String(error).includes('Executable doesn\'t exist')) {
      console.log('MISSING_CHROMIUM');
      process.exit(2);
    }
    throw error;
  }
  const html = fs.readFileSync('index.html', 'utf8');
  const axePath = '/tmp/axe.min.js';
  const results = {};
  for (const state of ['initial', 'invalid']) {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'load' });
    if (state === 'invalid') {
      await page.click('button[type="submit"]');
    }
    await page.addScriptTag({ path: axePath });
    const res = await page.evaluate(async () => await window.axe.run());
    results[state] = {
      wcag: res.violations.filter(v => !v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
      best_practice: res.violations.filter(v => v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
    };
    await page.close();
  }
  await browser.close();
  console.log(JSON.stringify(results));
  process.exit(Object.values(results).some(r => r.wcag.length) ? 1 : 0);
})();
